'use client';
import React, { useState, useEffect } from 'react';

export default function ScrollToTop() {
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    const toggleVisibility = () => {
      // Show button if scrolled down more than 400px
      if (window.scrollY > 400) {
        setIsVisible(true);
      } else {
        setIsVisible(false);
      }
    };

    window.addEventListener('scroll', toggleVisibility);
    return () => window.removeEventListener('scroll', toggleVisibility);
  }, []);

  const scrollToTop = () => {
    window.scrollTo({
      top: 0,
      behavior: 'smooth'
    });
  };

  return (
    <>
      <style>{`
        .scroll-to-top-btn {
          position: fixed;
          bottom: 30px;
          right: 30px;
          width: 44px;
          height: 44px;
          background-color: rgba(2, 4, 45, 0.85);
          border: 1px solid #e0c996;
          color: #e0c996;
          display: flex;
          align-items: center;
          justify-content: center;
          cursor: pointer;
          z-index: 999;
          transition: all 0.4s cubic-bezier(0.25, 1, 0.5, 1);
          opacity: 0;
          visibility: hidden;
          transform: translateY(15px);
          backdrop-filter: blur(6px);
        }
        
        .scroll-to-top-btn.visible {
          opacity: 1;
          visibility: visible;
          transform: translateY(0);
        }

        .scroll-to-top-btn:hover {
          background-color: #e0c996;
          color: #02042d;
          transform: translateY(-3px);
          box-shadow: 0 8px 20px rgba(224, 201, 150, 0.2);
        }

        .scroll-to-top-arrow {
          transition: transform 0.3s ease;
        }

        .scroll-to-top-btn:hover .scroll-to-top-arrow {
          transform: translateY(-2px);
        }
        
        @media (max-width: 768px) {
          .scroll-to-top-btn {
            bottom: 20px;
            right: 20px;
            width: 40px;
            height: 40px;
          }
        }
      `}</style>
      <button 
        onClick={scrollToTop}
        className={`scroll-to-top-btn ${isVisible ? 'visible' : ''}`}
        aria-label="Scroll to Top"
      >
        <span className="scroll-to-top-arrow" style={{ display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
          <svg viewBox="0 0 14 14" width="14" height="14" fill="none">
            <path 
              d="M7 13V1M7 1L2 6M7 1L12 6" 
              stroke="currentColor" 
              strokeWidth="1.5" 
              strokeLinecap="square" 
              strokeLinejoin="miter" 
            />
          </svg>
        </span>
      </button>
    </>
  );
}
