'use client';

import { useEffect, useRef } from 'react';
import { useRouter, usePathname } from 'next/navigation';
import gsap from 'gsap';

export default function PageTransition() {
  const overlayRef = useRef<HTMLDivElement>(null);
  const router = useRouter();
  const pathname = usePathname();
  const currentPath = useRef(pathname);
  const isAnimating = useRef(false);

  // Initialize GSAP positioning
  useEffect(() => {
    if (overlayRef.current) {
      gsap.set(overlayRef.current, { yPercent: 100 });
    }
  }, []);

  useEffect(() => {
    // When pathname changes naturally (e.g., initial load, or after our swipe up finishes)
    if (pathname !== currentPath.current && overlayRef.current) {
      currentPath.current = pathname;
      
      // Animate out (swipe down) to reveal the new page
      isAnimating.current = true;
      gsap.fromTo(overlayRef.current, 
        { yPercent: 0 },
        {
          yPercent: 100,
          duration: 0.8,
          ease: 'power3.inOut',
          onComplete: () => {
             isAnimating.current = false;
          }
        }
      );
    }
  }, [pathname]);

  useEffect(() => {
    const handleClick = (e: MouseEvent) => {
      const target = (e.target as HTMLElement).closest('a');
      if (!target || !target.href || target.target === '_blank') return;
      
      // Allow ctrl/cmd + click to open in new tab normally
      if (e.ctrlKey || e.metaKey || e.altKey || e.shiftKey) return;

      try {
        const url = new URL(target.href);
        const isInternal = url.origin === window.location.origin;
        const isAnchor = url.hash && url.pathname === window.location.pathname;

        if (isInternal && !isAnchor) {
          // Normalise pathnames to avoid trailing slash mismatches (though unlikely)
          const formatPath = (p: string) => p.endsWith('/') && p.length > 1 ? p.slice(0, -1) : p;
          
          if (formatPath(url.pathname) !== formatPath(pathname)) {
            e.preventDefault();
            e.stopPropagation();
            e.stopImmediatePropagation();
            
            if (overlayRef.current && !isAnimating.current) {
              isAnimating.current = true;
              // Animate overlay in (swipe up)
              gsap.fromTo(overlayRef.current, 
                { yPercent: 100 }, 
                { 
                  yPercent: 0, 
                  duration: 0.6, 
                  ease: 'power3.inOut',
                  onComplete: () => {
                    // Navigate only after overlay covers screen
                    router.push(url.pathname + url.search + url.hash);
                  }
                }
              );
            } else {
              router.push(url.pathname + url.search + url.hash);
            }
          }
        }
      } catch (err) {
        // Ignore invalid URLs
      }
    };

    // Use capture: true to intercept before Next.js Link component router logic
    document.addEventListener('click', handleClick, { capture: true });
    return () => document.removeEventListener('click', handleClick, { capture: true } as any);
  }, [pathname, router]);

  return (
    <div
      ref={overlayRef}
      style={{
        position: 'fixed',
        top: 0,
        left: 0,
        width: '100vw',
        height: '100dvh', // Use viewport units specifically
        backgroundColor: '#02042d', 
        zIndex: 999999, // Super high z-index
        pointerEvents: 'none',
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        willChange: 'transform' // Optimize GSAP transform
      }}
    >
      <div style={{ display: 'flex', alignItems: 'center', gap: '16px' }}>
        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1024 1024" width="64" height="64" fill="#e0c996">
          <g>
            <polygon points="571.3 966.5 572.2 569.1 835.9 852.3 836.9 524.5 709.7 452.1 707.8 675.9 654.9 620.2 654.9 362 887.9 495.8 889.1 966.5 843.4 966.5 623.3 711.2 623.3 966.5 571.3 966.5"/>
            <polygon points="572.2 528.2 621.4 579.3 621.4 236.7 449.7 57.5 449.7 804.9 413.5 753 413.5 285.9 327.1 342.5 327.1 672.2 217.5 794.7 216.6 413.1 134.9 464.2 134.9 966.5 157.2 966.5 344.8 766 481.2 966.5 497 966.5 497 466 498.1 180.6 557.3 240.9 572.6 255.8 572.2 528.2"/>
          </g>
        </svg>
        <div style={{ display: 'flex', flexDirection: 'column', lineHeight: 1 }}>
          <span style={{ fontFamily: '"Times New Roman", Times, serif', fontWeight: 'bold', fontSize: '48px', color: '#e0c996', letterSpacing: '0', display: 'block' }}>WeNest</span>
          <span style={{ fontFamily: '"Uxum Grotesque Light", sans-serif', fontSize: '23.5px', color: '#e0c996', letterSpacing: '0', display: 'block', marginTop: '-6px' }}>Real Estate LLC</span>
        </div>
      </div>
    </div>
  );
}
